import { useState, useEffect, useRef } from 'react'
import { Users, QrCode, Copy, Check, Wifi, RefreshCw, Shield, Smartphone } from 'lucide-react'
import EmptyState from '../components/EmptyState'
import { useStore } from '../store/useStore'
import toast from 'react-hot-toast'
import { useLanguage } from '../contexts/LanguageContext'
import { translations as t } from '../i18n'

const Pairing = () => {
  const { appState, pairWithPartner, generatePairCode } = useStore()
  const { language } = useLanguage()
  
  const [pairCodeInput, setPairCodeInput] = useState('')
  const [isGeneratingCode, setIsGeneratingCode] = useState(false)
  const [isPairing, setIsPairing] = useState(false)
  const [copied, setCopied] = useState(false)
  const [showQR, setShowQR] = useState(false)
  
  const qrCanvasRef = useRef<HTMLCanvasElement>(null)

  useEffect(() => {
    if (appState.pairCode) {
      generateQRCode(appState.pairCode)
    }
  }, [appState.pairCode])

  const generateQRCode = (text: string) => {
    if (!qrCanvasRef.current) return

    const canvas = qrCanvasRef.current
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height)

    // Simple QR code generation (in real app, use a proper QR library)
    const cellSize = 10
    const size = 29 // QR code version 3
    const margin = 4
    
    // Draw background
    ctx.fillStyle = 'white'
    ctx.fillRect(0, 0, canvas.width, canvas.height)

    // Draw QR code pattern (simplified)
    ctx.fillStyle = 'black'
    
    // Position markers
    drawPositionMarker(ctx, margin, margin, cellSize)
    drawPositionMarker(ctx, margin + (size - 7) * cellSize, margin, cellSize)
    drawPositionMarker(ctx, margin, margin + (size - 7) * cellSize, cellSize)

    // Draw text in center
    ctx.fillStyle = '#8b5cf6'
    ctx.font = 'bold 16px sans-serif'
    ctx.textAlign = 'center'
    ctx.textBaseline = 'middle'
    ctx.fillText(text.slice(0, 4), canvas.width / 2, canvas.height / 2 - 10)
    ctx.fillText(text.slice(4), canvas.width / 2, canvas.height / 2 + 10)
  }

  const drawPositionMarker = (ctx: CanvasRenderingContext2D, x: number, y: number, size: number) => {
    ctx.fillStyle = 'black'
    ctx.fillRect(x, y, size * 7, size * 7)
    
    ctx.fillStyle = 'white'
    ctx.fillRect(x + size, y + size, size * 5, size * 5)
    
    ctx.fillStyle = 'black'
    ctx.fillRect(x + size * 2, y + size * 2, size * 3, size * 3)
  }

  const handleGenerateCode = async () => {
    setIsGeneratingCode(true)
    
    try {
      const code = await generatePairCode()
      toast.success(`Generated pair code: ${code}`)
      setShowQR(true)
    } finally {
      setIsGeneratingCode(false)
    }
  }

  const handleCopyCode = () => {
    if (appState.pairCode) {
      navigator.clipboard.writeText(appState.pairCode)
      setCopied(true)
      toast.success('Pair code copied to clipboard!')
      
      setTimeout(() => {
        setCopied(false)
      }, 2000)
    }
  }

  const handlePair = async () => {
    if (!pairCodeInput.trim()) {
      toast.error('Please enter a pair code')
      return
    }

    setIsPairing(true)
    
    try {
      const success = await pairWithPartner(pairCodeInput.trim())
      if (success) {
        setPairCodeInput('')
      }
    } finally {
      setIsPairing(false)
    }
  }

  const handleResetPairing = () => {
    // This would reset pairing in real app
    toast.success('Pairing reset. Generate a new code to pair again.')
  }

  if (appState.isPaired) {
    return (
      <div className="space-y-6">
        {/* Already paired state */}
        <div className="text-center">
          <div className="w-20 h-20 bg-gradient-to-r from-green-100 to-green-200 rounded-full flex items-center justify-center mx-auto mb-4">
            <Users className="w-10 h-10 text-green-600" />
          </div>
          <h1 className="text-2xl font-bold text-gray-900 mb-2">
            {t.alreadyPaired[language]} 🎉
          </h1>
          <p className="text-gray-600">
            {t.connectedWith[language]} {appState.partnerName === 'ronald' ? 'Ronald' : 'Kerry'}
          </p>
        </div>

        {/* Pairing info */}
        <div className="bg-white border border-gray-200 rounded-xl p-6">
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-2">
                <Shield className="w-5 h-5 text-green-600" />
                <span className="font-medium text-gray-700">
                  {t.connectionStatus[language]}
                </span>
              </div>
              <div className="px-3 py-1 bg-green-100 text-green-800 rounded-full text-sm font-medium">
                {t.active[language]}
              </div>
            </div>

            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-gray-600">{t.pairCode[language]}</span>
                <span className="font-mono font-bold text-gray-900">{appState.pairCode}</span>
              </div>
              
              <div className="flex items-center justify-between">
                <span className="text-gray-600">{t.partner[language]}</span>
                <span className="font-medium text-gray-900">
                  {appState.partnerName === 'ronald' ? 'Ronald 👨‍💻' : 'Kerry 👩‍💻'}
                </span>
              </div>
              
              <div className="flex items-center justify-between">
                <span className="text-gray-600">{t.syncedPlaces[language]}</span>
                <span className="font-medium text-gray-900">
                  {t.allPlacesShared[language]}
                </span>
              </div>
            </div>
          </div>
        </div>

        {/* QR Code for easy re-pairing */}
        <div className="bg-white border border-gray-200 rounded-xl p-6">
          <h3 className="text-lg font-bold text-gray-900 mb-4">
            {t.quickPairCode[language]}
          </h3>
          <div className="flex flex-col items-center">
            <div className="border-2 border-dashed border-gray-300 rounded-lg p-4 mb-4">
              <canvas
                ref={qrCanvasRef}
                width={300}
                height={300}
                className="w-48 h-48"
              />
            </div>
            <p className="text-sm text-gray-600 text-center mb-4">
              {t.scanQRCode[language]}
            </p>
            <button
              onClick={handleCopyCode}
              className="flex items-center space-x-2 px-4 py-2 bg-gray-100 hover:bg-gray-200 rounded-lg font-medium"
            >
              {copied ? (
                <Check className="w-4 h-4 text-green-600" />
              ) : (
                <Copy className="w-4 h-4" />
              )}
              <span>{copied ? t.copied[language] : t.copyPairCode[language]}</span>
            </button>
          </div>
        </div>

        {/* Sync status */}
        <div className="bg-blue-50 rounded-xl p-6">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center space-x-2">
              <Wifi className="w-5 h-5 text-blue-600" />
              <h3 className="font-medium text-gray-900">
                {t.syncStatus[language]}
              </h3>
            </div>
            <div className={`px-3 py-1 rounded-full text-sm font-medium ${
              navigator.onLine ? 'bg-green-100 text-green-800' : 'bg-yellow-100 text-yellow-800'
            }`}>
              {navigator.onLine ? t.online[language] : t.offline[language]}
            </div>
          </div>
          
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-gray-600">{t.lastSync[language]}</span>
              <span className="text-gray-900">
                {new Date(appState.lastSync).toLocaleTimeString()}
              </span>
            </div>
            
            <div className="flex items-center justify-between">
              <span className="text-gray-600">{t.offlineChanges[language]}</span>
              <span className={`font-medium ${
                appState.offlineChanges > 0 ? 'text-yellow-600' : 'text-green-600'
              }`}>
                {appState.offlineChanges} {t.pending[language]}
              </span>
            </div>
          </div>
        </div>

        {/* Reset pairing */}
        <div className="text-center">
          <button
            onClick={handleResetPairing}
            className="px-6 py-3 border border-gray-300 rounded-lg font-medium hover:bg-gray-50 transition-colors"
          >
            {t.resetPairing[language]}
          </button>
          <p className="text-sm text-gray-500 mt-2">
            {t.resetPairingWarning[language]}
          </p>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Not paired state */}
      <EmptyState
        type="pairing"
        title={t.pairWithPartner[language]}
        description={t.pairWithPartnerDesc[language]}
        actionLabel={undefined}
      />

      {/* Pairing options */}
      <div className="space-y-6">
        {/* Option 1: Generate code */}
        <div className="bg-white border border-gray-200 rounded-xl p-6">
          <div className="flex items-start space-x-3 mb-4">
            <div className="w-10 h-10 bg-packet-purple rounded-lg flex items-center justify-center flex-shrink-0">
              <QrCode className="w-6 h-6 text-white" />
            </div>
            <div>
              <h3 className="text-lg font-bold text-gray-900">
                {t.generatePairCode[language]}
              </h3>
              <p className="text-gray-600">
                {t.createCodeDesc[language]}
              </p>
            </div>
          </div>

          {appState.pairCode ? (
            <div className="space-y-4">
              <div className="text-center">
                <div className="text-3xl font-mono font-bold text-packet-purple mb-2">
                  {appState.pairCode}
                </div>
                <p className="text-sm text-gray-600">
                  {t.shareCodeWithPartner[language]}
                </p>
              </div>

              {showQR && (
                <div className="border-2 border-dashed border-gray-300 rounded-lg p-4 flex flex-col items-center">
                  <canvas
                    ref={qrCanvasRef}
                    width={300}
                    height={300}
                    className="w-40 h-40"
                  />
                  <p className="text-sm text-gray-600 mt-2 text-center">
                    {t.partnerCanScan[language]}
                  </p>
                </div>
              )}

              <div className="flex space-x-3">
                <button
                  onClick={handleCopyCode}
                  className="flex-1 flex items-center justify-center space-x-2 py-3 bg-gray-100 hover:bg-gray-200 rounded-lg font-medium"
                >
                  {copied ? (
                    <Check className="w-5 h-5 text-green-600" />
                  ) : (
                    <Copy className="w-5 h-5" />
                  )}
                  <span>{copied ? t.copied[language] : t.copyCode[language]}</span>
                </button>
                <button
                  onClick={() => setShowQR(!showQR)}
                  className="flex-1 py-3 bg-packet-purple hover:bg-packet-purple-dark text-white rounded-lg font-medium"
                >
                  {showQR ? t.hideQR[language] : t.showQR[language]}
                </button>
              </div>
            </div>
          ) : (
            <button
              onClick={handleGenerateCode}
              disabled={isGeneratingCode}
              className="w-full py-3 bg-packet-purple hover:bg-packet-purple-dark text-white rounded-lg font-medium flex items-center justify-center space-x-2"
            >
              {isGeneratingCode ? (
                <RefreshCw className="w-5 h-5 animate-spin" />
              ) : (
                <QrCode className="w-5 h-5" />
              )}
              <span>{isGeneratingCode ? t.generating[language] : t.generatePairCode[language]}</span>
            </button>
          )}
        </div>

        {/* Option 2: Enter code */}
        <div className="bg-white border border-gray-200 rounded-xl p-6">
          <div className="flex items-start space-x-3 mb-4">
            <div className="w-10 h-10 bg-green-500 rounded-lg flex items-center justify-center flex-shrink-0">
              <Smartphone className="w-6 h-6 text-white" />
            </div>
            <div>
              <h3 className="text-lg font-bold text-gray-900">
                {t.enterPairCodeTitle[language]}
              </h3>
              <p className="text-gray-600">
                {t.enterCodeFromPartner[language]}
              </p>
            </div>
          </div>

          <div className="space-y-4">
            <div>
              <input
                type="text"
                value={pairCodeInput}
                onChange={(e) => setPairCodeInput(e.target.value.toUpperCase())}
                placeholder={t.pairCodePlaceholder[language]}
                className="input text-center font-mono text-lg"
              />
              <p className="text-sm text-gray-600 mt-2">
                {t.pairCodeFormat[language]}
              </p>
            </div>

            <button
              onClick={handlePair}
              disabled={isPairing || !pairCodeInput.trim()}
              className="w-full py-3 bg-green-500 hover:bg-green-600 text-white rounded-lg font-medium flex items-center justify-center space-x-2"
            >
              {isPairing ? (
                <RefreshCw className="w-5 h-5 animate-spin" />
              ) : (
                <Users className="w-5 h-5" />
              )}
              <span>{isPairing ? t.pairing[language] : t.pairNow[language]}</span>
            </button>
          </div>
        </div>

        {/* How it works */}
        <div className="bg-blue-50 rounded-xl p-6">
          <h3 className="text-lg font-bold text-gray-900 mb-4">
            {t.howPairingWorks[language]}
          </h3>
          <div className="space-y-4">
            <div className="flex items-start space-x-3">
              <div className="w-8 h-8 bg-white rounded-full flex items-center justify-center flex-shrink-0">
                <span className="font-bold text-blue-600">1</span>
              </div>
              <div>
                <div className="font-medium text-gray-900">
                  {t.pairingStep1[language]}
                </div>
                <div className="text-sm text-gray-600">
                  {t.pairingStep1Desc[language]}
                </div>
              </div>
            </div>
            
            <div className="flex items-start space-x-3">
              <div className="w-8 h-8 bg-white rounded-full flex items-center justify-center flex-shrink-0">
                <span className="font-bold text-blue-600">2</span>
              </div>
              <div>
                <div className="font-medium text-gray-900">
                  {t.pairingStep2[language]}
                </div>
                <div className="text-sm text-gray-600">
                  {t.pairingStep2Desc[language]}
                </div>
              </div>
            </div>
            
            <div className="flex items-start space-x-3">
              <div className="w-8 h-8 bg-white rounded-full flex items-center justify-center flex-shrink-0">
                <span className="font-bold text-blue-600">3</span>
              </div>
              <div>
                <div className="font-medium text-gray-900">
                  {t.pairingStep3[language]}
                </div>
                <div className="text-sm text-gray-600">
                  {t.pairingStep3Desc[language]}
                </div>
              </div>
            </div>
            
            <div className="flex items-start space-x-3">
              <div className="w-8 h-8 bg-white rounded-full flex items-center justify-center flex-shrink-0">
                <span className="font-bold text-blue-600">4</span>
              </div>
              <div>
                <div className="font-medium text-gray-900">
                  {t.pairingStep4[language]}
                </div>
                <div className="text-sm text-gray-600">
                  {t.pairingStep4Desc[language]}
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Security info */}
        <div className="bg-gray-50 rounded-xl p-6">
          <div className="flex items-center space-x-2 mb-4">
            <Shield className="w-5 h-5 text-gray-700" />
            <h3 className="font-medium text-gray-900">
              {t.privacySecurity[language]}
            </h3>
          </div>
          <ul className="text-sm text-gray-600 space-y-2">
            <li>• {t.privacyPoint1[language]}</li>
            <li>• {t.privacyPoint2[language]}</li>
            <li>• {t.privacyPoint3[language]}</li>
            <li>• {t.privacyPoint4[language]}</li>
            <li>• {t.privacyPoint5[language]}</li>
          </ul>
        </div>
      </div>
    </div>
  )
}

export default Pairing